#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define MAX_TENANTS 64
#define PAGE_POOL_SIZE 4096
#define FONT_TABLE_SIZE 256

typedef struct {
    uint32_t tenant_id;
    char tenant_name[32];
    uint8_t isolation_level;
} TenantContext;

typedef struct {
    void (*render_callback)(void *ctx, const uint8_t *data, size_t len);
    void (*cleanup)(void *ctx);
    void *userdata;
} PDFRenderOps;

typedef struct {
    uint32_t owner_tenant;
    uint8_t font_data[128];
    uint16_t glyph_count;
    uint16_t metrics_offset;
} FontEntry;

typedef struct {
    TenantContext tenants[MAX_TENANTS];
    FontEntry font_table[FONT_TABLE_SIZE];
    PDFRenderOps render_ops[MAX_TENANTS];
    uint8_t page_pool[PAGE_POOL_SIZE];
    uint32_t active_tenants;
    uint32_t current_tenant;
} PDFEngine;

static PDFEngine *g_engine = NULL;

int pdf_engine_init(void) {
    g_engine = (PDFEngine *)calloc(1, sizeof(PDFEngine));
    if (!g_engine) return -1;
    return 0;
}

int pdf_register_tenant(uint32_t tenant_id, const char *name, uint8_t iso_level) {
    if (!g_engine || g_engine->active_tenants >= MAX_TENANTS) return -1;
    uint32_t idx = g_engine->active_tenants;
    g_engine->tenants[idx].tenant_id = tenant_id;
    strncpy(g_engine->tenants[idx].tenant_name, name, 31);
    g_engine->tenants[idx].tenant_name[31] = '\0';
    g_engine->tenants[idx].isolation_level = iso_level;
    g_engine->active_tenants++;
    return 0;
}

int pdf_set_render_ops(uint32_t tenant_id, PDFRenderOps *ops) {
    if (!g_engine || !ops) return -1;
    for (uint32_t i = 0; i < g_engine->active_tenants; i++) {
        if (g_engine->tenants[i].tenant_id == tenant_id) {
            memcpy(&g_engine->render_ops[i], ops, sizeof(PDFRenderOps));
            return 0;
        }
    }
    return -1;
}

static int validate_font_index(uint32_t tenant_id, uint16_t font_idx) {
    if (font_idx >= FONT_TABLE_SIZE) return 0;
    /* Cross-tenant check: font must belong to requesting tenant */
    if (g_engine->font_table[font_idx].owner_tenant != tenant_id) return 0;
    return 1;
}

int pdf_load_font(uint32_t tenant_id, uint16_t font_idx, const uint8_t *data, size_t len) {
    if (!g_engine || font_idx >= FONT_TABLE_SIZE) return -1;
    if (!data) return -1;
    if (len > 128) len = 128;
    g_engine->font_table[font_idx].owner_tenant = tenant_id;
    memcpy(g_engine->font_table[font_idx].font_data, data, len);
    g_engine->font_table[font_idx].glyph_count = (uint16_t)(len / 2);
    g_engine->font_table[font_idx].metrics_offset = 0;
    return 0;
}

/* Core rendering path - processes PDF content stream operators */
int pdf_render_text(uint32_t tenant_id, uint16_t font_idx,
                    const uint8_t *text, size_t text_len,
                    uint16_t x_offset, uint16_t y_offset) {
    if (!g_engine) return -1;
    if (!text) return -1;

    /* Validate tenant isolation */
    if (!validate_font_index(tenant_id, font_idx)) return -1;

    FontEntry *font = &g_engine->font_table[font_idx];

    /* Calculate glyph render buffer position using metrics */
    uint32_t render_offset = (uint32_t)font->metrics_offset + 
                             (uint32_t)x_offset + 
                             (uint32_t)y_offset * 64;

    /* Bounds check against page pool - overflow-safe.
     * Ensure render_offset itself is in range, then check remaining space
     * against text_len without performing an addition that could wrap. */
    if (render_offset >= PAGE_POOL_SIZE) return -1;
    if (text_len > (size_t)(PAGE_POOL_SIZE - render_offset)) return -1;

    /* Render glyphs into page pool buffer */
    for (size_t i = 0; i < text_len; i++) {
        uint8_t glyph_id = text[i];
        if (glyph_id < font->glyph_count) {
            g_engine->page_pool[render_offset + i] = font->font_data[glyph_id * 2];
        }
    }

    return 0;
}

/* Composite glyph rendering - handles Type1 font subroutines */
int pdf_render_composite_glyph(uint32_t tenant_id, uint16_t font_idx,
                               uint16_t glyph_id, int16_t dx, int16_t dy) {
    if (!g_engine) return -1;
    if (!validate_font_index(tenant_id, font_idx)) return -1;

    FontEntry *font = &g_engine->font_table[font_idx];
    if (glyph_id >= font->glyph_count) return -1;

    /* Compute subroutine dispatch offset from glyph metrics.
     * The metrics_offset field is set during font loading and indicates
     * where in the font_data the metrics table begins. */
    uint16_t subroutine_base = font->metrics_offset;

    /* Apply displacement - signed arithmetic for bidirectional positioning */
    int32_t target_offset = (int32_t)subroutine_base + (int32_t)dx + (int32_t)dy * 8;

    /* Validate target is within page pool bounds */
    if (target_offset < 0 || (uint32_t)target_offset >= PAGE_POOL_SIZE - 8) return -1;

    /* Write composite glyph data into page pool as byte values only.
     * Never store pointer-sized values from user-controlled font data. */
    uint8_t glyph_lo = font->font_data[glyph_id * 2];
    uint8_t glyph_hi = font->font_data[glyph_id * 2 + 1];
    g_engine->page_pool[(uint32_t)target_offset] = glyph_lo;
    g_engine->page_pool[(uint32_t)target_offset + 1] = glyph_hi;

    return 0;
}

/* Rasterizer finalization - invokes render callbacks */
int pdf_finalize_page(uint32_t tenant_id) {
    if (!g_engine) return -1;

    int tenant_idx = -1;
    for (uint32_t i = 0; i < g_engine->active_tenants; i++) {
        if (g_engine->tenants[i].tenant_id == tenant_id) {
            tenant_idx = (int)i;
            break;
        }
    }
    if (tenant_idx < 0) return -1;

    PDFRenderOps *ops = &g_engine->render_ops[tenant_idx];
    if (ops->render_callback) {
        ops->render_callback(ops->userdata, g_engine->page_pool, PAGE_POOL_SIZE);
    }

    return 0;
}

/* Font metrics update - allows adjusting metrics_offset post-load */
int pdf_update_font_metrics(uint32_t tenant_id, uint16_t font_idx,
                            uint16_t new_metrics_offset) {
    if (!g_engine || font_idx >= FONT_TABLE_SIZE) return -1;
    if (!validate_font_index(tenant_id, font_idx)) return -1;

    /* The metrics offset points into font_data, validate accordingly */
    if (new_metrics_offset >= 128) return -1;

    g_engine->font_table[font_idx].metrics_offset = new_metrics_offset;
    return 0;
}

void pdf_engine_destroy(void) {
    if (g_engine) {
        memset(g_engine, 0, sizeof(PDFEngine));
        free(g_engine);
        g_engine = NULL;
    }
}
